# Extract the 9 reviews - they start after the header and end before the recall section
lines = context.split('\n')
reviews = []
for line in lines:
    if line.startswith('Date:') and 'Instance:' in line:
        reviews.append(line)

print(f"Found {len(reviews)} reviews")
for i, r in enumerate(reviews, 1):
    print(f"{i}. {r[:100]}...")
